// Current language
let currentLanguage = "en"

// Language switching functionality
function changeLanguage(lang) {
  currentLanguage = lang
  document.documentElement.lang = lang

  // Update all elements with data-i18n attribute
  document.querySelectorAll("[data-i18n]").forEach((element) => {
    const key = element.getAttribute("data-i18n")
    if (translations[lang][key]) {
      element.textContent = translations[lang][key]
    }
  })

  // Update active language button
  document.querySelectorAll(".lang-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.lang === lang)
  })

  // Apply RTL for Arabic
  if (lang === "ar") {
    document.body.style.direction = "rtl"
  } else {
    document.body.style.direction = "ltr"
  }
}

// Initialize Districts in all dropdowns
function initializeDistricts() {
  const districtSelects = document.querySelectorAll(".district-select")

  districtSelects.forEach((select) => {
    ugandaData.districts.forEach((district) => {
      const option = document.createElement("option")
      option.value = district.name
      option.textContent = district.name
      select.appendChild(option)
    })

    // Add change event listener for district
    select.addEventListener("change", function () {
      handleDistrictChange(this)
    })
  })

  // Add event listeners for county, subcounty, parish selects
  const countySelects = document.querySelectorAll(".county-select")
  countySelects.forEach((select) => {
    select.addEventListener("change", function () {
      handleCountyChange(this)
    })
  })

  const subCountySelects = document.querySelectorAll(".subcounty-select")
  subCountySelects.forEach((select) => {
    select.addEventListener("change", function () {
      handleSubCountyChange(this)
    })
  })

  const parishSelects = document.querySelectorAll(".parish-select")
  parishSelects.forEach((select) => {
    select.addEventListener("change", function () {
      handleParishChange(this)
    })
  })
}

// Handle cascading dropdowns
function handleDistrictChange(districtSelect) {
  const prefix = districtSelect.id.replace("District", "")
  const countySelect = document.getElementById(`${prefix}County`)
  const subCountySelect = document.getElementById(`${prefix}SubCounty`)
  const parishSelect = document.getElementById(`${prefix}Parish`)
  const villageSelect = document.getElementById(`${prefix}Village`)

  if (!countySelect) return

  // Reset all dependent dropdowns
  countySelect.innerHTML = '<option value="">--please select--</option>'
  countySelect.disabled = false

  if (subCountySelect) {
    subCountySelect.innerHTML = '<option value="">--please select--</option>'
    subCountySelect.disabled = true
  }
  if (parishSelect) {
    parishSelect.innerHTML = '<option value="">--please select--</option>'
    parishSelect.disabled = true
  }
  if (villageSelect) {
    villageSelect.innerHTML = '<option value="">--please select--</option>'
    villageSelect.disabled = true
  }

  const selectedDistrict = ugandaData.districts.find((d) => d.name === districtSelect.value)

  if (selectedDistrict) {
    selectedDistrict.counties.forEach((county) => {
      const option = document.createElement("option")
      option.value = county
      option.textContent = county
      countySelect.appendChild(option)
    })
  }
}

function handleCountyChange(countySelect) {
  const prefix = countySelect.id.replace("County", "")
  const subCountySelect = document.getElementById(`${prefix}SubCounty`)
  const parishSelect = document.getElementById(`${prefix}Parish`)
  const villageSelect = document.getElementById(`${prefix}Village`)

  if (!subCountySelect) return

  subCountySelect.innerHTML = '<option value="">--please select--</option>'
  subCountySelect.disabled = false

  if (parishSelect) {
    parishSelect.innerHTML = '<option value="">--please select--</option>'
    parishSelect.disabled = true
  }
  if (villageSelect) {
    villageSelect.innerHTML = '<option value="">--please select--</option>'
    villageSelect.disabled = true
  }

  const subs = subCounties[countySelect.value] || []
  subs.forEach((sub) => {
    const option = document.createElement("option")
    option.value = sub
    option.textContent = sub
    subCountySelect.appendChild(option)
  })
}

function handleSubCountyChange(subCountySelect) {
  const prefix = subCountySelect.id.replace("SubCounty", "")
  const parishSelect = document.getElementById(`${prefix}Parish`)
  const villageSelect = document.getElementById(`${prefix}Village`)

  if (!parishSelect) return

  parishSelect.innerHTML = '<option value="">--please select--</option>'
  parishSelect.disabled = false

  if (villageSelect) {
    villageSelect.innerHTML = '<option value="">--please select--</option>'
    villageSelect.disabled = true
  }

  const pars = parishes[subCountySelect.value] || []
  pars.forEach((par) => {
    const option = document.createElement("option")
    option.value = par
    option.textContent = par
    parishSelect.appendChild(option)
  })
}

function handleParishChange(parishSelect) {
  const prefix = parishSelect.id.replace("Parish", "")
  const villageSelect = document.getElementById(`${prefix}Village`)

  if (!villageSelect) return

  villageSelect.innerHTML = '<option value="">--please select--</option>'
  villageSelect.disabled = false

  const vils = villages[parishSelect.value] || []
  vils.forEach((vil) => {
    const option = document.createElement("option")
    option.value = vil
    option.textContent = vil
    villageSelect.appendChild(option)
  })
}

// Navigation
function initializeNavigation() {
  const prevBtn = document.getElementById("prevBtn")
  const nextBtn = document.getElementById("nextBtn")
  const saveExitBtn = document.getElementById("saveExitBtn")
  const submitBtn = document.getElementById("submitBtn")
  const navItems = document.querySelectorAll(".nav-item")
  const editBtns = document.querySelectorAll(".edit-btn")

  prevBtn.addEventListener("click", () => {
    if (currentStep > 1) {
      navigateToStep(currentStep - 1)
    }
  })

  nextBtn.addEventListener("click", () => {
    if (validateCurrentStep()) {
      if (currentStep < totalSteps) {
        navigateToStep(currentStep + 1)
      }
    }
  })

  saveExitBtn.addEventListener("click", () => {
    // Save draft via AJAX
    saveDraft()
  })

submitBtn.addEventListener("click", (e) => {
  e.preventDefault();

  Swal.fire({
    title: translations[currentLanguage]['alert.submit_confirm']
      || "Are you sure you want to submit this application?",
    icon: 'question',
    showCancelButton: true,
    confirmButtonText: 'Yes, Submit',
    cancelButtonText: 'Cancel',
    reverseButtons: true
  }).then((result) => {
    if (result.isConfirmed) {
      Swal.fire({
        title: 'Submitting...',
        html: 'Please wait while your application is being submitted.',
        allowOutsideClick: false,
        allowEscapeKey: false,
        didOpen: () => {
          Swal.showLoading();
          submitApplication();
        }
      });
    }
  });
});


  navItems.forEach((item) => {
    item.addEventListener("click", (e) => {
      e.preventDefault()
      const targetStep = Number.parseInt(item.getAttribute("data-section"))

      if (targetStep > currentStep) {
        // Check if all previous steps are valid
        let allPreviousValid = true
        for (let i = 1; i < targetStep; i++) {
          if (!validateStep(i)) {
            allPreviousValid = false
            break
          }
        }

        if (!allPreviousValid) {
          // SweetAlert
          Swal.fire({
            icon: 'warning',  // Can also use 'error', 'success', 'info'
            title: translations[currentLanguage]['alert.complete_previous'] || "Please complete all previous sections before proceeding.",
            confirmButtonText: 'OK',  // Text for the confirmation button
            customClass: {
              confirmButton: 'btn btn-outline'  // Optional: style button like Bootstrap
            }
          });
          return;
        }

      }

      navigateToStep(targetStep)
    })
  })

  editBtns.forEach((btn) => {
    btn.addEventListener("click", () => {
      const section = Number.parseInt(btn.dataset.section)
      navigateToStep(section)
    })
  })
}

function navigateToStep(step) {
  // Hide current section
  document.querySelectorAll(".form-section").forEach((section) => {
    section.classList.remove("active")
  })

  // Show target section
  const targetSection = document.getElementById(`section${step}`)
  if (targetSection) {
    targetSection.classList.add("active")
  }

  // Update navigation
  document.querySelectorAll(".nav-item").forEach((item, index) => {
    item.classList.toggle("active", index + 1 === step)
  })

  // Update progress
  currentStep = step
  updateProgress()
  updateButtons()

  // Scroll to top
  window.scrollTo({ top: 0, behavior: "smooth" })

  // If on review page, populate review data
  if (step === 6) {
    const appId = document.getElementById('application_db_id').value
    if (appId) {
      fetch(`/nikkah/${appId}`)
        .then((res) => res.json())
        .then((data) => {
          populateReview(null, data)
        })
        .catch(() => {
          populateReview()
        })
    } else {
      populateReview()
    }
  }
}

function updateProgress() {
  const progress = (currentStep / totalSteps) * 100
  document.getElementById("progressFill").style.width = progress + "%"

  // Update step indicators
  document.querySelectorAll(".step").forEach((step, index) => {
    if (index + 1 < currentStep) {
      step.classList.add("completed")
      step.classList.remove("active")
    } else if (index + 1 === currentStep) {
      step.classList.add("active")
      step.classList.remove("completed")
    } else {
      step.classList.remove("active", "completed")
    }
  })
}

function updateButtons() {
  const prevBtn = document.getElementById("prevBtn")
  const nextBtn = document.getElementById("nextBtn")
  const submitBtn = document.getElementById("submitBtn")

  prevBtn.style.display = currentStep === 1 ? "none" : "block"

  if (currentStep === totalSteps) {
    nextBtn.style.display = "none"
    submitBtn.style.display = "block"
  } else {
    nextBtn.style.display = "block"
    submitBtn.style.display = "none"
  }
}

function validateStep(stepNumber) {
  const section = document.getElementById(`section${stepNumber}`)
  const requiredInputs = section.querySelectorAll("[required]")
  let isValid = true

requiredInputs.forEach((input) => {
    const isEmpty = !input.value.trim();
    isValid = isValid && !isEmpty;

    // Check if input is a Select2 element
    if ($(input).hasClass('select2-hidden-accessible')) {
        const select2Container = $(input).next('.select2-container'); // Select2 renders after select
        if (isEmpty) {
            select2Container.find('.select2-selection').css('border-color', '#e74c3c');
        } else {
            select2Container.find('.select2-selection').css('border-color', '#e1e8ed');
        }
    } else {
        // Normal input
        input.style.borderColor = isEmpty ? "#e74c3c" : "#e1e8ed";
    }
});


  return isValid
}

function validateCurrentStep() {
  const currentSection = document.getElementById(`section${currentStep}`)
  const requiredInputs = currentSection.querySelectorAll("[required]")
  let isValid = true

  requiredInputs.forEach((input) => {
      const isEmpty = !input.value.trim();
      isValid = isValid && !isEmpty;

      if ($(input).hasClass('select2-hidden-accessible')) {
          const select2Container = $(input).next('.select2-container');
          if (isEmpty) {
              select2Container.find('.select2-selection').css('border-color', '#e74c3c');
          } else {
              select2Container.find('.select2-selection').css('border-color', '#e1e8ed');
          }
      } else {

          input.style.borderColor = isEmpty ? "#e74c3c" : "#e1e8ed";
      }
  });


  if (!isValid) {
    Swal.fire({
      icon: 'warning', // You can use 'error', 'success', etc.
      title: 'Oops...',
      text: translations[currentLanguage]['alert.fill_required'] || "Please fill in all required fields marked with *",
      confirmButtonText: 'OK'
    });
  }


  return isValid
}

// Photo Upload
function initializePhotoUpload() {
  setupPhotoUpload("groomPhoto", "groomPhotoPreview", "groomPhotoArea")
  setupPhotoUpload("bridePhoto", "bridePhotoPreview", "bridePhotoArea")
}

// Wire sidebar preview/save/submit buttons (if present on page)
document.addEventListener('DOMContentLoaded', () => {
  const previewBtn = document.getElementById('sidebarPreviewBtn')
  const saveBtn = document.getElementById('sidebarSaveBtn')
  const submitBtn = document.getElementById('sidebarSubmitBtn')

  if (previewBtn) {
    previewBtn.addEventListener('click', () => {
      try { storePreviewDataForRedirect() } catch (e) { }
      // open preview in new tab so user keeps the form
      window.open('/admin/invoices/create', '_blank')
    })
  }

  if (saveBtn) {
    saveBtn.addEventListener('click', () => {
      // trigger existing saveDraft flow
      try { saveDraft() } catch (e) { console.warn(e) }
    })
  }

  if (submitBtn) {
    submitBtn.addEventListener('click', () => {
      // trigger existing submit flow
      try { submitApplication() } catch (e) { console.warn(e) }
    })
  }
})

function setupPhotoUpload(inputId, previewId, areaId) {
  const input = document.getElementById(inputId)
  const preview = document.getElementById(previewId)
  const area = document.getElementById(areaId)

  input.addEventListener("change", (e) => {
    const file = e.target.files[0]
    if (file && file.type.startsWith("image/")) {
      const reader = new FileReader()
      reader.onload = (e) => {
        preview.src = e.target.result
        preview.style.display = "block"
        area.querySelector(".upload-placeholder").style.display = "none"
      }
      reader.readAsDataURL(file)
    }
  })

  // Drag and drop
  area.addEventListener("dragover", (e) => {
    e.preventDefault()
    area.style.borderColor = "#1e5128"
  })

  area.addEventListener("dragleave", () => {
    area.style.borderColor = "#ccc"
  })

  area.addEventListener("drop", (e) => {
    e.preventDefault()
    area.style.borderColor = "#ccc"

    const file = e.dataTransfer.files[0]
    if (file && file.type.startsWith("image/")) {
      input.files = e.dataTransfer.files
      const event = new Event("change")
      input.dispatchEvent(event)
    }
  })
}

