// CSRF helper
function getCsrfToken() {
  const meta = document.querySelector('meta[name="csrf-token"]')
  return (meta && meta.getAttribute('content')) || ''
}

// Save draft via AJAX
function saveDraft() {
  const form = document.getElementById('nikkahForm');
  const fd = new FormData(form);
  fd.set('status', 'draft');

  fetch('/nikkah/save', {
    method: 'POST',
    headers: {
      'X-CSRF-TOKEN': getCsrfToken(),
    },
    body: fd,
  })
    .then(async (r) => {
      if (r.status === 422) {
        const json = await r.json();
        displayErrors(json.errors || {});
        // scroll to first error on save
        try { scrollToFirstError(json.errors || {}); } catch (e) { }
        throw new Error('validation');
      }
      return r.json();
    })
    .then((json) => {
      clearErrors();
      if (json.success) {
        document.getElementById('application_db_id').value = json.id;
        document.getElementById('applicationId').textContent = json.application_id;

        // SweetAlert for success
        Swal.fire({
          icon: 'success',
          title: translations[currentLanguage]['alert.draft_saved'] || 'Draft saved.',
          text: `Application ID: ${json.application_id}`,
          confirmButtonText: 'OK',
        });

        // store preview images and basic form fields so preview shows immediately after redirect
        try { storePreviewDataForRedirect(); } catch (e) { }

        // Redirect to certificate preview page (same tab)
        window.location.href = `/admin/invoices/create?app=${json.id}`;
      } else {
        // SweetAlert for failure
        Swal.fire({
          icon: 'error',
          title: translations[currentLanguage]['alert.save_failed'] || 'Failed to save draft',
          confirmButtonText: 'OK',
        });
      }
    })
    .catch((err) => {
      if (err.message === 'validation') return;

      console.error(err);
      // SweetAlert for catch error
      Swal.fire({
        icon: 'error',
        title: 'Save failed.',
        text: 'Something went wrong while saving the draft.',
        confirmButtonText: 'OK',
      });
    });
}



function submitApplication() {
  const form = document.getElementById('nikkahForm');
  const fd = new FormData(form);
  fd.set('status', 'submitted');

  try { storePreviewDataForRedirect() } catch (e) {}

  const csrfToken = getCsrfToken();

  $.ajax({
    url: '/save-submitted-nikkah-application',
    method: 'POST',
    headers: {
      'X-CSRF-TOKEN': csrfToken,
    },
    data: fd,
    processData: false,
    contentType: false,
    dataType: 'json',

    success: function (json) {
      clearErrors();

      // 🔴 CLOSE loading Swal FIRST
      Swal.close();

      if (json.success) {

        if (document.getElementById('application_db_id')) {
          document.getElementById('application_db_id').value = json.id;
        }

        document.getElementById('applicationId').textContent = json.application_id;

        // ✅ Show success
        Swal.fire({
          icon: 'success',
          title: translations[currentLanguage]['alert.submit_success']
            || 'Application submitted successfully!',
          text: `Application ID: ${json.application_id}`,
          confirmButtonText: 'OK'
        }).then(() => {
          // ✅ Redirect after OK
          window.location.href = `/nikah-dashboard`;
        });

      } else {
        Swal.fire({
          icon: 'error',
          title: translations[currentLanguage]['alert.submit_failed']
            || 'Submission failed',
          confirmButtonText: 'OK',
        });
      }
    },

    error: function (xhr) {
      // 🔴 ALSO close loading Swal on error
      Swal.close();
      $('body').html(xhr.responseText);
    }
  });
}


// Error helpers
function clearErrors() {
  document.querySelectorAll('.field-error').forEach((el) => el.remove())
  document.querySelectorAll('.error-tooltip').forEach((el) => el.remove())
  document.querySelectorAll('[name]').forEach((el) => {
    el.style.borderColor = ''
  })
}

// Store preview data and images into sessionStorage before redirecting to certificate preview
function storePreviewDataForRedirect() {
  const form = document.getElementById('nikkahForm')
  if (!form) return

  const fd = new FormData(form)
  const previewData = {
    groom_given_name: fd.get('groom_given_name') || '',
    groom_surname: fd.get('groom_surname') || '',
    groom_nin: fd.get('groom_nin') || '',
    bride_given_name: fd.get('bride_given_name') || '',
    bride_surname: fd.get('bride_surname') || '',
    bride_nin: fd.get('bride_nin') || '',
    groom_father_given_name: fd.get('groom_father_given_name') || '',
    groom_father_surname: fd.get('groom_father_surname') || '',
    bride_father_given_name: fd.get('bride_father_given_name') || '',
    bride_father_surname: fd.get('bride_father_surname') || '',
    groom_district: fd.get('groom_district') || '',
    bride_district: fd.get('bride_district') || '',
    dowry_amount: fd.get('dowry_amount') || '',
    marriage_date: fd.get('marriage_date') || '',
    witness1_name: `${fd.get('witness1_given_name') || ''} ${fd.get('witness1_surname') || ''}`.trim(),
    witness1_address: fd.get('witness1_address') || '',
    witness2_name: `${fd.get('witness2_given_name') || ''} ${fd.get('witness2_surname') || ''}`.trim(),
    witness2_address: fd.get('witness2_address') || '',
    imam_name: fd.get('imam_name') || ''
  }

  // images: prefer preview elements if present
  const groomPreview = document.getElementById('groomPhotoPreview')
  const bridePreview = document.getElementById('bridePhotoPreview')
  if (groomPreview && groomPreview.src) sessionStorage.setItem('nikkah_preview_groom_photo', groomPreview.src)
  if (bridePreview && bridePreview.src) sessionStorage.setItem('nikkah_preview_bride_photo', bridePreview.src)

  sessionStorage.setItem('nikkah_preview_data', JSON.stringify(previewData))
}

function displayErrors(errors) {
  clearErrors()
  Object.keys(errors).forEach((field) => {
    const msgs = errors[field]
    const el = document.querySelector(`[name="${field}"]`)
    if (el) {
      // apply red border
      el.style.borderColor = '#e74c3c'

      // inline error text (for mobile / accessibility)
      const wrap = document.createElement('div')
      wrap.className = 'field-error'
      wrap.style.color = '#e74c3c'
      wrap.style.marginTop = '6px'
      wrap.style.fontSize = '13px'
      wrap.textContent = msgs.join(' ')
      if (el.parentNode) el.parentNode.appendChild(wrap)

      // floating tooltip (desktop)
      try {
        const tooltip = document.createElement('div')
        tooltip.className = 'error-tooltip'
        tooltip.textContent = msgs.join(' ')
        // ensure parent is positioned
        if (el.parentNode) el.parentNode.style.position = 'relative'
        // append tooltip to parent for absolute positioning
        if (el.parentNode) el.parentNode.appendChild(tooltip)
      } catch (e) {
        // ignore tooltip errors
      }
    }
  })

  // Scroll to and focus first error
  scrollToFirstError(errors)
}

function scrollToFirstError(errors) {
  const keys = Object.keys(errors)
  if (!keys.length) return
  const first = keys[0]
  const el = document.querySelector(`[name="${first}"]`)
  if (!el) return

  // navigate to the section containing the field (if any)
  const section = el.closest('.form-section')
  if (section && section.id && section.id.startsWith('section')) {
    const step = Number(section.id.replace('section', ''))
    if (!isNaN(step)) navigateToStep(step)
  }

  // scroll and focus
  setTimeout(() => {
    el.scrollIntoView({ behavior: 'smooth', block: 'center' })
    try { el.focus() } catch (e) { }
  }, 350)
}

// Language Selector Initialization
function initializeLanguageSelector() {
  // Existing buttons (if any)
  document.querySelectorAll(".lang-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      changeLanguage(btn.dataset.lang)
    })
  })

  // Links that navigate to /lang/{locale} — make them work without reload (set server session in background)
  document.querySelectorAll('a[href^="/lang/"]').forEach((link) => {
    link.addEventListener('click', (e) => {
      e.preventDefault()
      const href = link.getAttribute('href')
      const parts = href.split('/')
      const locale = parts[parts.length - 1]

      changeLanguage(locale)

      // Fire the server route to persist selection, but don't reload
      fetch(href, { method: 'GET', credentials: 'same-origin' }).catch(() => { })
    })
  })
}

// Initialize
document.addEventListener("DOMContentLoaded", () => {
  // Set current language from server if present
  if (window.appLocale) {
    currentLanguage = window.appLocale
    changeLanguage(currentLanguage)
  }

  initializeDistricts()
  initializeNavigation()
  initializePhotoUpload()
  initializeLanguageSelector()
  updateProgress()
})








